        cmds=[json.loads(m.group(1)) for m in re.finditer(r'"?cmd"?\s*:\s*("(?:\\.|[^"\\])*")',s)]
        op=[]
        for cmd in cmds:
            if "python3 - <<'PY'\n" not in cmd:continue
            body=cmd.split("python3 - <<'PY'\n",1)[1].rsplit('\nPY',1)[0]
            for node in ast.walk(ast.parse(body)):
                if isinstance(node,ast.Call):
                    name=ast.unparse(node.func)
                    if any(name.endswith(x) for x in ['write_text','write_bytes','mkdir','open','unlink','remove','rmtree','rename','replace','exec','eval','run','check_output']):
